-- Music Land: paste this whole file into Supabase > SQL Editor and press Run.
-- GENERATED by `npm run gen:seed`. Safe to run again after changing game data.

-- Music Land: schema + game rules. Safe to run again (and on top of an older version).
--
-- Clients can only SELECT their own rows; every change goes through the
-- security definer functions below, so EXP, zeny and drops are decided here.
-- Menu actions (create, stats, skills, shop, equip) are called by the browser.
-- Combat results, potions, death, HP/position and trades are called only by the
-- Colyseus game server with the service role key, passing the player's user id.

create table if not exists public.class_defs (
  id text primary key,
  base_stats jsonb not null,
  start_weapon text not null
);

create table if not exists public.item_defs (
  id text primary key,
  type text not null,
  price int not null,
  classes text[],
  in_shop boolean not null default false
);
alter table public.item_defs add column if not exists weight int not null default 1;
alter table public.item_defs drop constraint if exists item_defs_type_check;
alter table public.item_defs add constraint item_defs_type_check
  check (type in ('consumable', 'loot', 'card', 'weapon', 'armor', 'head', 'accessory', 'shoes', 'earring'));
-- card slots on equipment; for cards, the equipment type they go into (see cardFits in src/data/index.ts)
alter table public.item_defs add column if not exists slots int not null default 0;
alter table public.item_defs add column if not exists card_slot text;
-- outfits (VRoid models) only fit one gender: 'm' / 'f' (null = anyone). See wearBlock in src/data/index.ts
alter table public.item_defs add column if not exists gender text;
-- which NPC shop sells it: 'shop' = the item shop (ป้ามะลิ's list, cheaper with ต่อราคาเก่ง), 'weapons' = the weapon shop
alter table public.item_defs add column if not exists shop_kind text;

create table if not exists public.monster_defs (
  id text primary key,
  exp int not null,
  zeny_min int not null,
  zeny_max int not null,
  drops jsonb not null default '[]'
);
alter table public.monster_defs add column if not exists job_exp int not null default 0;
alter table public.monster_defs add column if not exists level int not null default 1;

create table if not exists public.skill_defs (
  id text primary key,
  cls text not null,
  max_level int not null
);

create table if not exists public.characters (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null unique check (char_length(name) between 2 and 16),
  cls text not null references public.class_defs (id),
  level int not null default 1,
  exp int not null default 0,
  zeny int not null default 100,
  stat_points int not null default 0,
  str int not null, agi int not null, vit int not null, "int" int not null, dex int not null,
  hp int not null default -1,
  sp int not null default -1,
  pos_x real not null default 48.5,
  pos_y real not null default 55.5,
  last_kill_at timestamptz,
  created_at timestamptz not null default now()
);
alter table public.characters add column if not exists luk int not null default 1;
alter table public.characters add column if not exists gender text not null default 'm';
alter table public.characters add column if not exists hair int not null default 0;
alter table public.characters add column if not exists hair_color int not null default 0;
alter table public.characters add column if not exists face int not null default 0;
alter table public.characters add column if not exists job_level int not null default 1;
alter table public.characters add column if not exists job_exp int not null default 0;
alter table public.characters add column if not exists skill_points int not null default 0;
alter table public.characters add column if not exists skills jsonb not null default '{}';
alter table public.characters add column if not exists map text not null default 'town';
-- job-change quest: -1 = not taken, else kills so far (see change_job)
alter table public.characters add column if not exists job_quest int not null default -1;
create index if not exists characters_user_idx on public.characters (user_id);

create table if not exists public.inventory (
  id uuid primary key default gen_random_uuid(),
  character_id uuid not null references public.characters (id) on delete cascade,
  item_id text not null references public.item_defs (id),
  qty int not null check (qty > 0),
  equipped boolean not null default false
);
create index if not exists inventory_char_idx on public.inventory (character_id);
-- equipment only: + level from the refiner, and the cards inserted into it
alter table public.inventory add column if not exists refine int not null default 0;
alter table public.inventory add column if not exists cards text[] not null default '{}';

-- บูรพา's storage: one per account (auth user), shared by all of that account's characters.
-- Stackable items keep one row per item; each piece of equipment is its own row (qty 1).
create table if not exists public.account_storage (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  item_id text not null references public.item_defs (id),
  qty int not null check (qty > 0)
);
create index if not exists account_storage_user_idx on public.account_storage (user_id);
alter table public.account_storage add column if not exists refine int not null default 0;
alter table public.account_storage add column if not exists cards text[] not null default '{}';

alter table public.class_defs enable row level security;
alter table public.item_defs enable row level security;
alter table public.monster_defs enable row level security;
alter table public.skill_defs enable row level security;
alter table public.characters enable row level security;
alter table public.inventory enable row level security;
alter table public.account_storage enable row level security;

drop policy if exists "defs readable" on public.class_defs;
create policy "defs readable" on public.class_defs for select using (true);
drop policy if exists "defs readable" on public.item_defs;
create policy "defs readable" on public.item_defs for select using (true);
drop policy if exists "defs readable" on public.monster_defs;
create policy "defs readable" on public.monster_defs for select using (true);
drop policy if exists "defs readable" on public.skill_defs;
create policy "defs readable" on public.skill_defs for select using (true);

drop policy if exists "own characters" on public.characters;
create policy "own characters" on public.characters for select to authenticated using (user_id = auth.uid());
drop policy if exists "delete own characters" on public.characters;
create policy "delete own characters" on public.characters for delete to authenticated using (user_id = auth.uid());

drop policy if exists "own inventory" on public.inventory;
create policy "own inventory" on public.inventory for select to authenticated
  using (exists (select 1 from public.characters c where c.id = character_id and c.user_id = auth.uid()));

drop policy if exists "own storage" on public.account_storage;
create policy "own storage" on public.account_storage for select to authenticated using (user_id = auth.uid());

revoke insert, update on public.characters, public.inventory from anon, authenticated;
revoke insert, update, delete on public.account_storage from anon, authenticated;

-- older versions of these functions had other parameters
drop function if exists public.create_character(text, text);
drop function if exists public.create_character(text, text, text, int, int, int);
drop function if exists public.report_kill(uuid, text);
drop function if exists public.use_item(uuid, uuid);
drop function if exists public.save_state(uuid, int, int, real, real);
drop function if exists public.save_state(uuid, uuid, int, int, real, real);
drop function if exists public.on_death(uuid);
drop function if exists public._own_char(uuid);

-- ---------------------------------------------------------------- formulas (match src/data/index.ts)

-- the last levels are harder: Lv 60-89 +100%, 90 +200%, 91-95 +500%, 96-97 +1000%, 98-99 +2000%
create or replace function public.exp_hard(lvl int) returns int
language sql immutable as $$
  select case when lvl >= 98 then 21 when lvl >= 96 then 11 when lvl >= 91 then 6 when lvl = 90 then 3 when lvl >= 60 then 2 else 1 end
$$;

create or replace function public.exp_to_next(lvl int) returns int
language sql immutable as $$ select (floor(15 * power(lvl::float8, 1.9))::int + 10) * public.exp_hard(lvl) $$;

create or replace function public.job_exp_to_next(lvl int) returns int
language sql immutable as $$ select floor(12 * power(lvl::float8, 1.8))::int + 8 $$;

create or replace function public.stat_cost(cur int) returns int
language sql immutable as $$ select (cur - 1) / 10 + 2 $$;

-- status points a stat at p_value is worth when reset to 1 (statRefund in src/data/index.ts)
create or replace function public._stat_refund(p_value int) returns int
language sql immutable as $$ select coalesce(sum(public.stat_cost(v)), 0)::int from generate_series(1, p_value - 1) v $$;

-- ---------------------------------------------------------------- helpers

create or replace function public._own_char(p_char uuid, p_user uuid default null) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters;
begin
  select * into c from public.characters where id = p_char and user_id = coalesce(p_user, auth.uid()) for update;
  if not found then raise exception 'ไม่พบตัวละคร'; end if;
  return c;
end $$;

create or replace function public._add_item(p_char uuid, p_item text, p_qty int) returns void
language plpgsql security definer set search_path = public as $$
declare t text;
begin
  select type into t from public.item_defs where id = p_item;
  if t is null then raise exception 'unknown item %', p_item; end if;
  if t in ('weapon', 'armor', 'head', 'accessory', 'shoes', 'earring') then
    insert into public.inventory (character_id, item_id, qty)
      select p_char, p_item, 1 from generate_series(1, p_qty);
  else
    update public.inventory set qty = qty + p_qty where character_id = p_char and item_id = p_item;
    if not found then
      insert into public.inventory (character_id, item_id, qty) values (p_char, p_item, p_qty);
    end if;
  end if;
end $$;

create or replace function public._char_json(c public.characters) returns jsonb
language sql immutable as $$ select to_jsonb(c) - 'user_id' - 'last_kill_at' - 'created_at' $$;

revoke execute on function public._own_char(uuid, uuid) from public, anon, authenticated;
revoke execute on function public._add_item(uuid, text, int) from public, anon, authenticated;

-- ---------------------------------------------------------------- menu actions (browser)

-- every new character starts as a Teen (class 1); class 2 comes from change_job()
create or replace function public.create_character(
  p_name text, p_gender text, p_hair int, p_hair_color int, p_face int
) returns public.characters
language plpgsql security definer set search_path = public as $$
declare d public.class_defs; c public.characters;
begin
  if auth.uid() is null then raise exception 'ต้องล็อกอินก่อน'; end if;
  p_name := btrim(p_name);
  if char_length(p_name) not between 2 and 16 then raise exception 'ชื่อต้องยาว 2-16 ตัวอักษร'; end if;
  if (select count(*) from public.characters where user_id = auth.uid()) >= 3 then
    raise exception 'สร้างได้สูงสุด 3 ตัวละคร';
  end if;
  if exists (select 1 from public.characters where name = p_name) then raise exception 'ชื่อนี้ถูกใช้แล้ว'; end if;
  if p_gender not in ('m', 'f') or p_hair not between 0 and 63 or p_hair_color not between 0 and 7 or p_face not between 0 and 3 then
    raise exception 'หน้าตาไม่ถูกต้อง';
  end if;
  select * into d from public.class_defs where id = 'teen';
  if not found then raise exception 'ไม่มีอาชีพนี้'; end if;

  insert into public.characters (user_id, name, cls, str, agi, vit, "int", dex, luk, gender, hair, hair_color, face)
  values (auth.uid(), p_name, 'teen',
    (d.base_stats->>'str')::int, (d.base_stats->>'agi')::int, (d.base_stats->>'vit')::int,
    (d.base_stats->>'int')::int, (d.base_stats->>'dex')::int, (d.base_stats->>'luk')::int,
    p_gender, p_hair, p_hair_color, p_face)
  returning * into c;

  insert into public.inventory (character_id, item_id, qty, equipped) values (c.id, d.start_weapon, 1, true);
  perform public._add_item(c.id, 'water', 5);
  return c;
end $$;

create or replace function public.allocate_stat(p_char uuid, p_stat text) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; cur int; cost int;
begin
  c := public._own_char(p_char);
  if p_stat not in ('str', 'agi', 'vit', 'int', 'dex', 'luk') then raise exception 'bad stat'; end if;
  execute format('select %I from public.characters where id = $1', p_stat) into cur using p_char;
  if cur >= 99 then raise exception 'สเตตัสเต็มแล้ว'; end if;
  cost := public.stat_cost(cur);
  if c.stat_points < cost then raise exception 'แต้มสเตตัสไม่พอ (ต้องใช้ %)', cost; end if;
  execute format('update public.characters set %I = %I + 1, stat_points = stat_points - $2 where id = $1', p_stat, p_stat)
    using p_char, cost;
  select * into c from public.characters where id = p_char;
  return c;
end $$;

create or replace function public.learn_skill(p_char uuid, p_skill text) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; s public.skill_defs; cur int;
begin
  c := public._own_char(p_char);
  select * into s from public.skill_defs where id = p_skill;
  -- cls 'all' = every class (เปิดแผงขายของ)
  if not found or (s.cls <> c.cls and s.cls <> 'all') then raise exception 'อาชีพนี้เรียนสกิลนี้ไม่ได้'; end if;
  cur := coalesce((c.skills->>p_skill)::int, 0);
  if cur >= s.max_level then raise exception 'สกิลเต็มแล้ว'; end if;
  if c.skill_points < 1 then raise exception 'แต้มสกิลไม่พอ'; end if;
  update public.characters
    set skills = skills || jsonb_build_object(p_skill, cur + 1), skill_points = skill_points - 1
    where id = p_char returning * into c;
  return c;
end $$;

-- job change (numbers match JOB_CHANGE in src/data/index.ts): a Teen at Base Lv 10 takes the quest,
-- kills 30 monsters of Lv 10+ (counted in report_kill), then picks a class 2
create or replace function public.start_job_quest(p_char uuid) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters;
begin
  c := public._own_char(p_char);
  if c.cls <> 'teen' then raise exception 'เปลี่ยนอาชีพไปแล้ว'; end if;
  if c.level < 10 then raise exception 'ต้องมี Base Lv 10 ก่อน'; end if;
  update public.characters set job_quest = greatest(job_quest, 0) where id = p_char returning * into c;
  return c;
end $$;

create or replace function public.change_job(p_char uuid, p_cls text) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; d public.class_defs; v_town text;
begin
  c := public._own_char(p_char);
  if c.cls <> 'teen' then raise exception 'เปลี่ยนอาชีพไปแล้ว'; end if;
  if p_cls not in ('singer', 'guitarist', 'drummer', 'bassist', 'keyboardist') then raise exception 'ไม่มีอาชีพนี้'; end if;
  if c.level < 10 or c.job_quest < 30 then raise exception 'ยังทำเควสไม่สำเร็จ'; end if;
  -- each class is handed out in its own town (JOB_TOWN in src/data/index.ts): drummers in the desert,
  -- keyboardists in the city of magic, everyone else in the first town
  -- (the town goes into a variable first: inside IF ... THEN, plpgsql would stop at the CASE's own THEN)
  v_town := case p_cls when 'drummer' then 'desert' when 'keyboardist' then 'magic' else 'town' end;
  if c.map <> v_town then
    raise exception 'ต้องเปลี่ยนอาชีพนี้ที่%', case v_town when 'desert' then 'เมืองทะเลทรายตะโพน' when 'magic' then 'เมืองคีย์มนตรา' else 'เมืองเมโลเดีย' end;
  end if;
  select * into d from public.class_defs where id = p_cls;
  update public.inventory inv set equipped = false
    from public.item_defs i
    where inv.character_id = p_char and inv.equipped and i.id = inv.item_id and i.type = 'weapon';
  insert into public.inventory (character_id, item_id, qty, equipped) values (p_char, d.start_weapon, 1, true);
  -- a fresh start for the new class: every stat back to 1 with its points refunded, and the Teen skills
  -- are dropped with their skill points refunded (only the new class's skills can be learned)
  update public.characters set cls = p_cls, job_level = 1, job_exp = 0, job_quest = -1,
    stat_points = stat_points + public._stat_refund(str) + public._stat_refund(agi) + public._stat_refund(vit)
      + public._stat_refund("int") + public._stat_refund(dex) + public._stat_refund(luk),
    str = 1, agi = 1, vit = 1, "int" = 1, dex = 1, luk = 1,
    skill_points = skill_points + (select coalesce(sum(greatest(0, e.value::int)), 0) from jsonb_each_text(skills) e
      where e.key in (select id from public.skill_defs where cls = 'teen')),
    skills = (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(skills) e
      where e.key not in (select id from public.skill_defs where cls = 'teen'))
    where id = p_char returning * into c;
  return c;
end $$;

create or replace function public.buy_item(p_char uuid, p_item text, p_qty int) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; v_price int;
begin
  c := public._own_char(p_char);
  select case when i.shop_kind = 'shop'
      -- ต่อราคาเก่ง (Teen): 2.5% off per level on the item shop's list (npcBuyPrice in src/data/index.ts)
      then greatest(1, (i.price * (1000 - least(500, coalesce((c.skills->>'haggle')::int, 0) * 25))) / 1000)
      else i.price end
    into v_price from public.item_defs i where i.id = p_item and i.in_shop;
  if v_price is null or p_qty < 1 or p_qty > 99 then raise exception 'ซื้อไม่ได้'; end if;
  if c.zeny < v_price * p_qty then raise exception 'เงินไม่พอ'; end if;
  update public.characters set zeny = zeny - v_price * p_qty where id = p_char returning * into c;
  perform public._add_item(p_char, p_item, p_qty);
  return c;
end $$;

create or replace function public.sell_item(p_char uuid, p_inv uuid, p_qty int) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; r public.inventory; v_price int;
begin
  c := public._own_char(p_char);
  select * into r from public.inventory where id = p_inv and character_id = p_char for update;
  if not found or r.equipped or p_qty < 1 or p_qty > r.qty then raise exception 'ขายไม่ได้'; end if;
  select i.price into v_price from public.item_defs i where i.id = r.item_id;
  if r.qty = p_qty then delete from public.inventory where id = p_inv;
  else update public.inventory set qty = qty - p_qty where id = p_inv; end if;
  -- ปากหวานขายเก่ง (Teen): 2.5% more per level (npcSellPrice in src/data/index.ts)
  v_price := ((v_price / 2) * (1000 + coalesce((c.skills->>'sweet_talk')::int, 0) * 25)) / 1000;
  update public.characters set zeny = zeny + v_price * p_qty where id = p_char returning * into c;
  return c;
end $$;

create or replace function public.set_equipped(p_char uuid, p_inv uuid, p_equipped boolean) returns void
language plpgsql security definer set search_path = public as $$
declare c public.characters; r public.inventory; it public.item_defs;
begin
  c := public._own_char(p_char);
  select * into r from public.inventory where id = p_inv and character_id = p_char;
  if not found then raise exception 'ไม่พบไอเท็ม'; end if;
  select * into it from public.item_defs where id = r.item_id;
  if it.type not in ('weapon', 'armor', 'head', 'accessory', 'shoes', 'earring') then raise exception 'สวมใส่ไม่ได้'; end if;
  if p_equipped and it.classes is not null and not (c.cls = any (it.classes)) then
    raise exception 'อาชีพนี้ใช้ไม่ได้';
  end if;
  if p_equipped and it.gender is not null and c.gender <> it.gender then
    raise exception '%', case when it.gender = 'f' then 'ชุดนี้สำหรับตัวละครหญิง' else 'ชุดนี้สำหรับตัวละครชาย' end;
  end if;
  if p_equipped then
    update public.inventory inv set equipped = false
      from public.item_defs i
      where inv.character_id = p_char and inv.equipped and i.id = inv.item_id and i.type = it.type;
  end if;
  update public.inventory set equipped = p_equipped where id = p_inv;
end $$;

-- ---------------------------------------------------------------- game server only

-- Adds a reward to one character: EXP (with level ups), zeny, items, and a job-quest kill.
-- report_kill rolls a monster's reward for one player; the game server calls this directly
-- with each member's share when a party splits a kill.
create or replace function public.grant_reward(
  p_user uuid, p_char uuid, p_exp int, p_job_exp int, p_zeny int, p_items text[], p_quest boolean
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c public.characters; it text; start_level int; start_job int;
  max_level constant int := 99; max_job constant int := 50;
begin
  c := public._own_char(p_char, p_user);
  foreach it in array coalesce(p_items, '{}') loop
    perform public._add_item(p_char, it, 1);
  end loop;

  start_level := c.level;
  start_job := c.job_level;
  c.zeny := c.zeny + greatest(p_zeny, 0);
  if c.level < max_level then c.exp := c.exp + greatest(p_exp, 0); end if;
  while c.level < max_level and c.exp >= public.exp_to_next(c.level) loop
    c.exp := c.exp - public.exp_to_next(c.level);
    c.level := c.level + 1;
    c.stat_points := c.stat_points + c.level / 5 + 3;
  end loop;
  if c.level >= max_level then c.exp := 0; end if;
  if c.job_level < max_job then c.job_exp := c.job_exp + greatest(p_job_exp, 0); end if;
  while c.job_level < max_job and c.job_exp >= public.job_exp_to_next(c.job_level) loop
    c.job_exp := c.job_exp - public.job_exp_to_next(c.job_level);
    c.job_level := c.job_level + 1;
    c.skill_points := c.skill_points + 1;
  end loop;
  if c.job_level >= max_job then c.job_exp := 0; end if;
  if p_quest and c.job_quest >= 0 and c.job_quest < 30 then c.job_quest := c.job_quest + 1; end if;

  update public.characters
    set zeny = c.zeny, exp = c.exp, level = c.level, stat_points = c.stat_points,
        job_exp = c.job_exp, job_level = c.job_level, skill_points = c.skill_points, job_quest = c.job_quest,
        last_kill_at = now()
    where id = p_char returning * into c;

  return jsonb_build_object(
    'character', public._char_json(c), 'drops', to_jsonb(coalesce(p_items, '{}')), 'zeny', greatest(p_zeny, 0),
    'exp', greatest(p_exp, 0), 'jobExp', greatest(p_job_exp, 0),
    'leveledUp', c.level > start_level, 'jobLeveledUp', c.job_level > start_job);
end $$;

create or replace function public.report_kill(p_user uuid, p_char uuid, p_monster text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare m public.monster_defs; d jsonb; got text[] := '{}';
begin
  perform public._own_char(p_char, p_user);
  select * into m from public.monster_defs where id = p_monster;
  if not found then raise exception 'unknown monster'; end if;
  for d in select * from jsonb_array_elements(m.drops) loop
    if random() < (d->>1)::float8 then got := got || (d->>0); end if;
  end loop;
  return public.grant_reward(p_user, p_char, m.exp, m.job_exp,
    m.zeny_min + floor(random() * (m.zeny_max - m.zeny_min + 1))::int, got, m.level >= 10);
end $$;

create or replace function public.use_item(p_user uuid, p_char uuid, p_inv uuid) returns text
language plpgsql security definer set search_path = public as $$
declare r public.inventory;
begin
  perform public._own_char(p_char, p_user);
  select inv.* into r from public.inventory inv join public.item_defs i on i.id = inv.item_id
    where inv.id = p_inv and inv.character_id = p_char and i.type = 'consumable' for update of inv;
  if not found then raise exception 'ใช้ไม่ได้'; end if;
  if r.qty = 1 then delete from public.inventory where id = p_inv;
  else update public.inventory set qty = qty - 1 where id = p_inv; end if;
  return r.item_id;
end $$;

create or replace function public.save_state(
  p_user uuid, p_char uuid, p_hp int, p_sp int, p_map text, p_x real, p_y real
) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public._own_char(p_char, p_user);
  update public.characters
    set hp = greatest(p_hp, 1), sp = greatest(p_sp, 0), map = p_map,
        pos_x = least(greatest(p_x, 0), 200), pos_y = least(greatest(p_y, 0), 200)
    where id = p_char;
end $$;

create or replace function public.on_death(p_user uuid, p_char uuid) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters;
begin
  c := public._own_char(p_char, p_user);
  update public.characters
    set exp = greatest(0, exp - floor(public.exp_to_next(level) * 0.05)::int), map = 'town', pos_x = 48.5, pos_y = 55.5
    where id = p_char returning * into c;
  return c;
end $$;

-- บูรพา's storage (browser). The account is the character's owner; one lock per account so two
-- of its characters can't race each other. Numbers match STORAGE_SLOTS in src/data/index.ts.
create or replace function public.storage_put(p_char uuid, p_inv uuid, p_qty int) returns void
language plpgsql security definer set search_path = public as $$
declare c public.characters; r public.inventory; t text; s_id uuid;
begin
  c := public._own_char(p_char);
  perform pg_advisory_xact_lock(hashtext('storage:' || c.user_id::text));
  select * into r from public.inventory where id = p_inv and character_id = p_char for update;
  if not found or r.equipped or p_qty < 1 or p_qty > r.qty then raise exception 'ฝากไม่ได้'; end if;
  select type into t from public.item_defs where id = r.item_id;
  if t not in ('weapon', 'armor', 'head', 'accessory', 'shoes', 'earring') then
    select id into s_id from public.account_storage where user_id = c.user_id and item_id = r.item_id limit 1;
  end if;
  if s_id is null and (select count(*) from public.account_storage where user_id = c.user_id) >= 300 then
    raise exception 'คลังเต็ม (300 ช่อง)';
  end if;
  if r.qty = p_qty then delete from public.inventory where id = p_inv;
  else update public.inventory set qty = qty - p_qty where id = p_inv; end if;
  if s_id is null then
    insert into public.account_storage (user_id, item_id, qty, refine, cards) values (c.user_id, r.item_id, p_qty, r.refine, r.cards);
  else update public.account_storage set qty = qty + p_qty where id = s_id; end if;
end $$;

create or replace function public.storage_take(p_char uuid, p_row uuid, p_qty int) returns void
language plpgsql security definer set search_path = public as $$
declare c public.characters; s public.account_storage; t text;
begin
  c := public._own_char(p_char);
  perform pg_advisory_xact_lock(hashtext('storage:' || c.user_id::text));
  select * into s from public.account_storage where id = p_row and user_id = c.user_id for update;
  if not found or p_qty < 1 or p_qty > s.qty then raise exception 'ถอนไม่ได้'; end if;
  if s.qty = p_qty then delete from public.account_storage where id = p_row;
  else update public.account_storage set qty = qty - p_qty where id = p_row; end if;
  select type into t from public.item_defs where id = s.item_id;
  if t in ('weapon', 'armor', 'head', 'accessory', 'shoes', 'earring') then
    -- equipment keeps its + level and cards
    insert into public.inventory (character_id, item_id, qty, refine, cards)
      select p_char, s.item_id, 1, s.refine, s.cards from generate_series(1, p_qty);
  else
    perform public._add_item(p_char, s.item_id, p_qty);
  end if;
end $$;

-- Monster cards (browser): put one card from the bag into a free card slot of a piece of equipment.
-- The card is used up; only the card remover NPC (remove_cards) can take it out again.
create or replace function public.insert_card(p_char uuid, p_card uuid, p_equip uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c public.characters; cr public.inventory; er public.inventory; ci public.item_defs; ei public.item_defs;
begin
  c := public._own_char(p_char);
  select * into cr from public.inventory where id = p_card and character_id = p_char for update;
  select * into er from public.inventory where id = p_equip and character_id = p_char for update;
  if cr.id is null or er.id is null then raise exception 'ไม่พบไอเท็ม'; end if;
  select * into ci from public.item_defs where id = cr.item_id;
  select * into ei from public.item_defs where id = er.item_id;
  if ci.type <> 'card' then raise exception 'ไอเท็มนี้ไม่ใช่การ์ด'; end if;
  if not (ci.card_slot = ei.type or (ci.card_slot = 'head' and ei.type = 'earring')) then
    raise exception 'การ์ดใบนี้เสียบในไอเท็มนี้ไม่ได้';
  end if;
  if coalesce(array_length(er.cards, 1), 0) >= ei.slots then raise exception 'ไม่มีช่องการ์ดว่าง'; end if;
  if cr.qty = 1 then delete from public.inventory where id = p_card;
  else update public.inventory set qty = qty - 1 where id = p_card; end if;
  update public.inventory set cards = cards || cr.item_id where id = p_equip;
end $$;

-- Refiner NPC (browser). Numbers match REFINE in src/data/index.ts: 1 material + 100 z x next level;
-- the material changes after +4 (REFINE.lowMax);
-- up to the safe level it always works, past it a failure destroys the item and its cards.
create or replace function public.refine_item(p_char uuid, p_inv uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c public.characters; r public.inventory; it public.item_defs; nxt int; chance int; fee int; mat text; m public.inventory;
  ok boolean;
begin
  c := public._own_char(p_char);
  select * into r from public.inventory where id = p_inv and character_id = p_char for update;
  if not found then raise exception 'ไม่พบไอเท็ม'; end if;
  select * into it from public.item_defs where id = r.item_id;
  if it.type not in ('weapon', 'armor', 'head', 'shoes', 'earring') then raise exception 'ไอเท็มนี้ตีบวกไม่ได้'; end if;
  if r.refine >= 10 then raise exception 'ตีบวกสูงสุดแล้ว (+10)'; end if;
  nxt := r.refine + 1;
  -- +1..+4 use the low materials (drops from Lv 10-30 monsters), +5..+10 the high ones (Lv 40-99)
  if it.type = 'weapon' then
    chance := (array[100, 100, 100, 100, 100, 70, 55, 40, 25, 15])[nxt];
    mat := case when nxt <= 4 then 'tuning_ore' else 'pure_tuning_ore' end;
  else
    chance := (array[100, 100, 100, 100, 70, 55, 40, 30, 20, 10])[nxt];
    mat := case when nxt <= 4 then 'velvet_patch' else 'gold_velvet' end;
  end if;
  fee := 100 * nxt;
  if c.zeny < fee then raise exception 'Zeny ไม่พอ (ค่าตีบวก % z)', fee; end if;
  select * into m from public.inventory where character_id = p_char and item_id = mat for update limit 1;
  if not found then
    raise exception 'ไม่มี%', case mat when 'tuning_ore' then 'หินจูนเสียง' when 'velvet_patch' then 'ผ้ากำมะหยี่ซับเสียง'
      when 'pure_tuning_ore' then 'หินจูนเสียงบริสุทธิ์' else 'ผ้ากำมะหยี่ทองซับเสียง' end;
  end if;
  if m.qty = 1 then delete from public.inventory where id = m.id;
  else update public.inventory set qty = qty - 1 where id = m.id; end if;
  update public.characters set zeny = zeny - fee where id = p_char returning * into c;
  ok := random() * 100 < chance;
  if ok then
    update public.inventory set refine = nxt where id = p_inv;
  else
    delete from public.inventory where id = p_inv;
  end if;
  return jsonb_build_object('ok', ok, 'refine', case when ok then nxt else r.refine end, 'character', public._char_json(c));
end $$;

-- Reset NPC (browser). Fees match SERVICE_FEE in src/data/index.ts.
-- Status reset: every stat back to 1 and all the points they were worth refunded (same sum as the job change).
create or replace function public.reset_stats(p_char uuid) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; fee constant int := 10000;
begin
  c := public._own_char(p_char);
  if c.str = 1 and c.agi = 1 and c.vit = 1 and c."int" = 1 and c.dex = 1 and c.luk = 1 then
    raise exception 'สเตตัสเป็น 1 ทั้งหมดอยู่แล้ว';
  end if;
  if c.zeny < fee then raise exception 'Zeny ไม่พอ (ค่ารีเซ็ต % z)', fee; end if;
  update public.characters set zeny = zeny - fee,
    stat_points = stat_points + public._stat_refund(str) + public._stat_refund(agi) + public._stat_refund(vit)
      + public._stat_refund("int") + public._stat_refund(dex) + public._stat_refund(luk),
    str = 1, agi = 1, vit = 1, "int" = 1, dex = 1, luk = 1
    where id = p_char returning * into c;
  return c;
end $$;

-- Skill reset: every learned skill back to Lv 0 and its points refunded.
create or replace function public.reset_skills(p_char uuid) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; fee constant int := 10000; back int;
begin
  c := public._own_char(p_char);
  select coalesce(sum(greatest(0, e.value::int)), 0) into back from jsonb_each_text(c.skills) e;
  if back = 0 then raise exception 'ยังไม่ได้เรียนสกิลเลย'; end if;
  if c.zeny < fee then raise exception 'Zeny ไม่พอ (ค่ารีเซ็ต % z)', fee; end if;
  update public.characters set zeny = zeny - fee, skill_points = skill_points + back, skills = '{}'::jsonb
    where id = p_char returning * into c;
  return c;
end $$;

-- Card remover NPC (browser): takes every card out of one piece of equipment and puts them back in the bag.
create or replace function public.remove_cards(p_char uuid, p_inv uuid) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; r public.inventory; fee constant int := 10000; card text;
begin
  c := public._own_char(p_char);
  select * into r from public.inventory where id = p_inv and character_id = p_char for update;
  if not found then raise exception 'ไม่พบไอเท็ม'; end if;
  if coalesce(array_length(r.cards, 1), 0) = 0 then raise exception 'ไอเท็มนี้ไม่มีการ์ด'; end if;
  if c.zeny < fee then raise exception 'Zeny ไม่พอ (ค่าถอดการ์ด % z)', fee; end if;
  update public.characters set zeny = zeny - fee where id = p_char returning * into c;
  update public.inventory set cards = '{}' where id = p_inv;
  foreach card in array r.cards loop
    perform public._add_item(p_char, card, 1);
  end loop;
  return c;
end $$;

-- the bot shops in town (game server only): ป้ามะลิ's list at 90% (botShopPrice in server/src/bots.ts)
create or replace function public.bot_shop_buy(p_user uuid, p_char uuid, p_item text, p_qty int) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters; v_price int;
begin
  c := public._own_char(p_char, p_user);
  select greatest(1, (i.price * 9) / 10) into v_price from public.item_defs i where i.id = p_item and i.shop_kind = 'shop';
  if v_price is null or p_qty < 1 or p_qty > 999 then raise exception 'ซื้อไม่ได้'; end if;
  if c.zeny < v_price * p_qty then raise exception 'เงินไม่พอ'; end if;
  update public.characters set zeny = zeny - v_price * p_qty where id = p_char returning * into c;
  perform public._add_item(p_char, p_item, p_qty);
  return c;
end $$;
-- บูรพา's warp (game server only): pay the fare and move in one step.
create or replace function public.pay_warp(
  p_user uuid, p_char uuid, p_cost int, p_hp int, p_sp int, p_map text, p_x real, p_y real
) returns public.characters
language plpgsql security definer set search_path = public as $$
declare c public.characters;
begin
  c := public._own_char(p_char, p_user);
  if p_cost < 0 then raise exception 'bad fare'; end if;
  if c.zeny < p_cost then raise exception 'Zeny ไม่พอ (ค่าวาร์ป % z)', p_cost; end if;
  update public.characters
    set zeny = zeny - p_cost, hp = greatest(p_hp, 1), sp = greatest(p_sp, 0), map = p_map,
        pos_x = least(greatest(p_x, 0), 200), pos_y = least(greatest(p_y, 0), 200)
    where id = p_char returning * into c;
  return c;
end $$;

-- Swap items and zeny between two characters in one transaction.
-- p_items_*: [{"inv": "<inventory id>", "qty": n}, ...] offered by that side.
create or replace function public.trade_execute(
  p_user_a uuid, p_char_a uuid, p_items_a jsonb, p_zeny_a int,
  p_user_b uuid, p_char_b uuid, p_items_b jsonb, p_zeny_b int
) returns void
language plpgsql security definer set search_path = public as $$
declare
  a public.characters; b public.characters;
  side int; giver uuid; taker uuid; offer jsonb; o jsonb; r public.inventory; t text; q int;
begin
  if p_char_a = p_char_b then raise exception 'แลกกับตัวเองไม่ได้'; end if;
  -- lock both in a fixed order to avoid deadlocks
  if p_char_a < p_char_b then
    a := public._own_char(p_char_a, p_user_a); b := public._own_char(p_char_b, p_user_b);
  else
    b := public._own_char(p_char_b, p_user_b); a := public._own_char(p_char_a, p_user_a);
  end if;
  if p_zeny_a < 0 or p_zeny_b < 0 or a.zeny < p_zeny_a or b.zeny < p_zeny_b then raise exception 'เงินไม่พอ'; end if;

  for side in 1..2 loop
    if side = 1 then giver := p_char_a; taker := p_char_b; offer := p_items_a;
    else giver := p_char_b; taker := p_char_a; offer := p_items_b; end if;
    for o in select * from jsonb_array_elements(coalesce(offer, '[]')) loop
      q := (o->>'qty')::int;
      select * into r from public.inventory where id = (o->>'inv')::uuid and character_id = giver for update;
      if not found or r.equipped or q < 1 or q > r.qty then raise exception 'ไอเท็มที่แลกไม่ถูกต้อง'; end if;
      select type into t from public.item_defs where id = r.item_id;
      if t in ('weapon', 'armor', 'head', 'accessory', 'shoes', 'earring') then
        update public.inventory set character_id = taker, equipped = false where id = r.id;
      else
        if q = r.qty then delete from public.inventory where id = r.id;
        else update public.inventory set qty = qty - q where id = r.id; end if;
        perform public._add_item(taker, r.item_id, q);
      end if;
    end loop;
  end loop;

  update public.characters set zeny = zeny - p_zeny_a + p_zeny_b where id = p_char_a;
  update public.characters set zeny = zeny - p_zeny_b + p_zeny_a where id = p_char_b;
end $$;

