-- refund and remove skills that no longer exist
update public.characters c set skill_points = c.skill_points + (select coalesce(sum(greatest(0, (e.value)::int)), 0) from jsonb_each_text(c.skills) e where e.key not in ('quick_slash', 'dash_stab', 'whirl_stab', 'pump_up', 'tough_body', 'dynamics', 'warm_up', 'enunciation', 'ear_training', 'breath_control', 'high_voice', 'hammer_on', 'slide', 'vibrato', 'bending', 'arpeggio', 'palm_muting', 'snare_roll', 'ghost_exit', 'double_kick', 'send_off', 'x_wave', 'collect_exp', 'root_note', 'kick_drum', 'straight_beat', 'lift_beat', 'push_note', 'pluck_control', 'note_blast', 'restore', 'tempo_up', 'tempo_control', 'solo', 'chorus_ward', 'revive', 'open_shop', 'haggle', 'sweet_talk')), skills = (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(c.skills) e where e.key in ('quick_slash', 'dash_stab', 'whirl_stab', 'pump_up', 'tough_body', 'dynamics', 'warm_up', 'enunciation', 'ear_training', 'breath_control', 'high_voice', 'hammer_on', 'slide', 'vibrato', 'bending', 'arpeggio', 'palm_muting', 'snare_roll', 'ghost_exit', 'double_kick', 'send_off', 'x_wave', 'collect_exp', 'root_note', 'kick_drum', 'straight_beat', 'lift_beat', 'push_note', 'pluck_control', 'note_blast', 'restore', 'tempo_up', 'tempo_control', 'solo', 'chorus_ward', 'revive', 'open_shop', 'haggle', 'sweet_talk')) where exists (select 1 from jsonb_object_keys(c.skills) k where k not in ('quick_slash', 'dash_stab', 'whirl_stab', 'pump_up', 'tough_body', 'dynamics', 'warm_up', 'enunciation', 'ear_training', 'breath_control', 'high_voice', 'hammer_on', 'slide', 'vibrato', 'bending', 'arpeggio', 'palm_muting', 'snare_roll', 'ghost_exit', 'double_kick', 'send_off', 'x_wave', 'collect_exp', 'root_note', 'kick_drum', 'straight_beat', 'lift_beat', 'push_note', 'pluck_control', 'note_blast', 'restore', 'tempo_up', 'tempo_control', 'solo', 'chorus_ward', 'revive', 'open_shop', 'haggle', 'sweet_talk'));
delete from public.skill_defs where id not in ('quick_slash', 'dash_stab', 'whirl_stab', 'pump_up', 'tough_body', 'dynamics', 'warm_up', 'enunciation', 'ear_training', 'breath_control', 'high_voice', 'hammer_on', 'slide', 'vibrato', 'bending', 'arpeggio', 'palm_muting', 'snare_roll', 'ghost_exit', 'double_kick', 'send_off', 'x_wave', 'collect_exp', 'root_note', 'kick_drum', 'straight_beat', 'lift_beat', 'push_note', 'pluck_control', 'note_blast', 'restore', 'tempo_up', 'tempo_control', 'solo', 'chorus_ward', 'revive', 'open_shop', 'haggle', 'sweet_talk');

-- Teen skills only work for Teens now: characters who already changed job get those skill points back
update public.characters c set skill_points = c.skill_points + (select coalesce(sum(greatest(0, (e.value)::int)), 0) from jsonb_each_text(c.skills) e where e.key in (select id from public.skill_defs where cls = 'teen')), skills = (select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(c.skills) e where e.key not in (select id from public.skill_defs where cls = 'teen')) where c.cls <> 'teen' and exists (select 1 from jsonb_object_keys(c.skills) k where k in (select id from public.skill_defs where cls = 'teen'));
